#!/usr/bin/env python3
"""
BIEK Computer Science 12th Class Past Paper Analysis (2015-2025)
Generates a comprehensive trend analysis HTML report with embedded charts.
"""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from matplotlib.patches import FancyBboxPatch
from collections import Counter
import re
import base64
import io
import json
from textwrap import wrap

# ── Configuration ──────────────────────────────────────────────────
PRIMARY = "#1e3a5f"
SECONDARY = "#2c7da0"
ACCENT = "#f4a261"
HIGHLIGHT = "#e76f51"
NEUTRAL = "#6b7280"
LIGHT_BG = "#f8f9fa"
MCQ_COLOR = "#2c7da0"
SHORT_COLOR = "#f4a261"
LONG_COLOR = "#e76f51"

YEAR_COLORS = [
    "#1e3a5f", "#234b70", "#2c5f8a", "#3573a5", "#3e87bf",
    "#f4a261", "#e8854d", "#e76f51", "#d45a40", "#c94a30"
]

plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'font.size': 11,
    'axes.titlesize': 14,
    'axes.titleweight': 'bold',
    'axes.labelweight': 'bold',
    'figure.dpi': 120,
    'savefig.dpi': 120,
    'savefig.bbox': 'tight',
    'savefig.pad_inches': 0.2,
})


def fig_to_base64(fig):
    """Convert matplotlib figure to base64 PNG string."""
    buf = io.BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return f"data:image/png;base64,{b64}"


# ── Load & Prepare Data ────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
years_list = sorted(df['year'].unique())
total_questions = len(df)

# Yearly counts by type
year_type = df.groupby(['year', 'type']).size().unstack(fill_value=0)
year_type = year_type.reindex(columns=['MCQs', 'Short', 'Long'])
year_totals = year_type.sum(axis=1)

# Compute year-over-year changes
yoy_abs = year_totals.diff()
yoy_pct = year_totals.pct_change() * 100

# Overall type totals
type_totals = df['type'].value_counts()

# Identify 2020 missing
has_2020 = 2020 in years_list


# ── Chart 1: Total Questions per Year (Line Chart) ─────────────────
fig1, ax1 = plt.subplots(figsize=(10, 5))
years_labels = [str(y) for y in years_list]
ax1.plot(years_labels, year_totals.values, color=PRIMARY, linewidth=2.5, marker='o', markersize=8, markerfacecolor=ACCENT, markeredgecolor=PRIMARY, markeredgewidth=1.5)
for i, (yr, val) in enumerate(zip(years_labels, year_totals.values)):
    ax1.annotate(str(val), (yr, val), textcoords="offset points", xytext=(0, 12), ha='center', fontsize=10, fontweight='bold', color=PRIMARY)
if not has_2020:
    ax1.axvline(x=4.5, color=NEUTRAL, linestyle='--', alpha=0.7, linewidth=1)
    ax1.annotate('2020 data\nnot available', xy=(4.5, ax1.get_ylim()[1] * 0.85), ha='center', fontsize=9, color=NEUTRAL, fontstyle='italic')
ax1.set_ylabel('Number of Questions', fontweight='bold')
ax1.set_xlabel('Examination Year', fontweight='bold')
ax1.set_title('Total Questions per Year (2015–2025)', fontsize=15, fontweight='bold', color=PRIMARY)
ax1.set_ylim(bottom=20, top=max(year_totals.values) + 6)
ax1.yaxis.set_major_locator(mticker.MaxNLocator(integer=True))
ax1.grid(axis='y', alpha=0.3, linestyle='--')
ax1.spines['top'].set_visible(False)
ax1.spines['right'].set_visible(False)
chart1_b64 = fig_to_base64(fig1)


# ── Chart 2: Stacked Bar – Question Type Distribution by Year ──────
fig2, ax2 = plt.subplots(figsize=(10, 5.5))
bar_colors = [MCQ_COLOR, SHORT_COLOR, LONG_COLOR]
bottom = np.zeros(len(years_list))
for idx, qtype in enumerate(['MCQs', 'Short', 'Long']):
    vals = year_type[qtype].values
    bars = ax2.bar(years_labels, vals, bottom=bottom, color=bar_colors[idx], label=qtype, edgecolor='white', linewidth=0.5)
    # Add value labels on bars > 5
    for i, (b, v) in enumerate(zip(bars, vals)):
        if v > 2:
            ax2.text(b.get_x() + b.get_width()/2, bottom[i] + v/2, str(v), ha='center', va='center', fontsize=9, fontweight='bold', color='white')
    bottom += vals
ax2.set_ylabel('Number of Questions', fontweight='bold')
ax2.set_xlabel('Examination Year', fontweight='bold')
ax2.set_title('Question Type Composition by Year', fontsize=15, fontweight='bold', color=PRIMARY)
ax2.legend(loc='upper right', framealpha=0.9, edgecolor='#ddd')
ax2.yaxis.set_major_locator(mticker.MaxNLocator(integer=True))
ax2.spines['top'].set_visible(False)
ax2.spines['right'].set_visible(False)
chart2_b64 = fig_to_base64(fig2)


# ── Chart 3: Percentage Share (Stacked Area / 100% bar) ───────────
fig3, ax3 = plt.subplots(figsize=(10, 5))
pct_data = year_type.div(year_totals, axis=0) * 100
for idx, qtype in enumerate(['MCQs', 'Short', 'Long']):
    ax3.plot(years_labels, pct_data[qtype].values, color=bar_colors[idx], linewidth=2.5, marker='o', markersize=6, label=qtype)
ax3.set_ylabel('Percentage of Total (%)', fontweight='bold')
ax3.set_xlabel('Examination Year', fontweight='bold')
ax3.set_title('Question Type Proportion Trends (2015–2025)', fontsize=15, fontweight='bold', color=PRIMARY)
ax3.legend(loc='center right', framealpha=0.9, edgecolor='#ddd')
ax3.set_ylim(0, 65)
ax3.grid(axis='y', alpha=0.3, linestyle='--')
ax3.spines['top'].set_visible(False)
ax3.spines['right'].set_visible(False)
chart3_b64 = fig_to_base64(fig3)


# ── Chart 4: Overall Type Share (Pie Chart) ────────────────────────
fig4, ax4 = plt.subplots(figsize=(7, 7))
wedges, texts, autotexts = ax4.pie(
    type_totals.values, labels=type_totals.index, autopct='%1.1f%%',
    colors=[MCQ_COLOR, SHORT_COLOR, LONG_COLOR], startangle=140,
    explode=(0.02, 0.02, 0.08), textprops={'fontsize': 12, 'fontweight': 'bold'},
    pctdistance=0.7
)
for at in autotexts:
    at.set_fontweight('bold')
    at.set_fontsize(11)
    at.set_color('white')
ax4.set_title('Overall Question Type Distribution (All Years)', fontsize=15, fontweight='bold', color=PRIMARY)
chart4_b64 = fig_to_base64(fig4)


# ── Chart 5: Year-over-Year Change (Bar) ───────────────────────────
fig5, ax5 = plt.subplots(figsize=(10, 5))
changes = yoy_abs.dropna().values
change_years = yoy_abs.dropna().index.astype(str).tolist()
bar_colors_5 = [ACCENT if v >= 0 else HIGHLIGHT for v in changes]
bars = ax5.bar(change_years, changes, color=bar_colors_5, edgecolor='white', linewidth=0.8)
for b, v in zip(bars, changes):
    y_pos = b.get_height() + (0.5 if v >= 0 else -2.5)
    va = 'bottom' if v >= 0 else 'top'
    ax5.text(b.get_x() + b.get_width()/2, y_pos, f'{v:+.0f}', ha='center', va=va, fontsize=11, fontweight='bold', color=PRIMARY)
ax5.axhline(y=0, color='#333', linewidth=0.8)
ax5.set_ylabel('Change in Total Questions', fontweight='bold')
ax5.set_xlabel('Year Transition', fontweight='bold')
ax5.set_title('Year-over-Year Change in Question Volume', fontsize=15, fontweight='bold', color=PRIMARY)
ax5.spines['top'].set_visible(False)
ax5.spines['right'].set_visible(False)
ax5.grid(axis='y', alpha=0.3, linestyle='--')
chart5_b64 = fig_to_base64(fig5)


# ── Topic / Keyword Analysis ───────────────────────────────────────
STOP_WORDS = {
    'the','a','an','is','are','of','in','to','for','this','and','or',
    'that','it','be','on','with','at','by','as','from','has','its','not',
    'can','we','use','an','i','ii','iii','iv','v','vi','vii','viii','ix',
    'x','xi','xii','xiii','xiv','xv','xvi','xvii','xviii','xix','xx','was',
    'all','each','used','if','do','so','no','will','what','which','how',
    'any','also','does','may','one','two','three','four','give','given',
    'using','following','called','write','like','much','would','very','get',
    'been','yes','etc','eg','ie','without','since','value','values','make',
    'more','just','some','into','up','out','their','when','but','your',
    'only','about','than','over','let','then','int'
}

def clean_text(text):
    text = str(text).replace('$', ' ')
    text = re.sub(r'[^a-zA-Z\s]', ' ', text)
    text = re.sub(r'\s+', ' ', text).strip().lower()
    return text

# Aggregate all question text
all_text = ' '.join(df['question'].apply(clean_text))
words = all_text.split()
filtered = [w for w in words if w not in STOP_WORDS and len(w) > 2]
overall_freq = Counter(filtered)

# Group related terms into topic clusters
TOPIC_CLUSTERS = {
    'C Programming Fundamentals': ['program', 'language', 'main', 'compiler', 'syntax', 'preprocessor', 'directive', 'comment', 'identifier', 'reserved', 'source', 'object', 'code', 'execution', 'flowchart', 'algorithm', 'header'],
    'Data Types & Variables': ['types', 'variable', 'constant', 'integer', 'float', 'character', 'string', 'char', 'format', 'specifier', 'printf', 'scanf', 'declaration', 'int', 'double', 'size', 'bytes'],
    'Control Structures': ['loop', 'while', 'iteration', 'selection', 'nested', 'break', 'continue', 'condition', 'control', 'structure', 'conditional'],
    'Functions': ['function', 'recursive', 'recursion', 'prototype', 'parameter', 'argument', 'void', 'return', 'library', 'user', 'calling'],
    'Operators & Expressions': ['operator', 'operators', 'arithmetic', 'logical', 'relational', 'expression', 'precedence', 'assignment', 'increment', 'decrement', 'unary', 'ternary'],
    'Database Concepts': ['database', 'dbms', 'relational', 'model', 'attribute', 'entity', 'tuple', 'schema', 'normalization', 'integrity', 'redundancy', 'dba', 'transaction'],
    'SQL & DB Languages': ['sql', 'dml', 'ddl', 'dcl', 'tcl', 'query', 'language', 'manipulation', 'definition'],
    'Keys & Relationships': ['key', 'primary', 'foreign', 'composite', 'candidate', 'alternate', 'super', 'relationship', 'referential', 'unique'],
    'MS Access Objects': ['access', 'table', 'form', 'report', 'query', 'macro', 'module', 'objects'],
    'File Handling': ['file', 'input', 'output', 'mode', 'fclose', 'fopen', 'stream', 'gets', 'puts', 'read', 'reading'],
    'Arrays & Data Structures': ['array', 'index', 'element', 'structure', 'union', 'pointer'],
}

topic_scores = {}
for topic, keywords in TOPIC_CLUSTERS.items():
    score = sum(overall_freq.get(kw, 0) for kw in keywords)
    topic_scores[topic] = score

topic_scores_sorted = sorted(topic_scores.items(), key=lambda x: x[1], reverse=True)

# Topic by question type
def type_topic_scores(type_filter):
    type_text = ' '.join(df[df['type'] == type_filter]['question'].apply(clean_text))
    words_type = type_text.split()
    filtered_type = [w for w in words_type if w not in STOP_WORDS and len(w) > 2]
    freq = Counter(filtered_type)
    scores = {}
    for topic, keywords in TOPIC_CLUSTERS.items():
        scores[topic] = sum(freq.get(kw, 0) for kw in keywords)
    return scores

mcq_topics = type_topic_scores('MCQs')
short_topics = type_topic_scores('Short')
long_topics = type_topic_scores('Long')


# ── Chart 6: Topic Frequency (Horizontal Bar) ───────────────────────
fig6, ax6 = plt.subplots(figsize=(10, 6.5))
topics = [t[0] for t in topic_scores_sorted]
scores = [t[1] for t in topic_scores_sorted]
colors_topics = [PRIMARY, "#2c7da0", "#3e87bf", ACCENT, HIGHLIGHT, "#264653", "#2a9d8f", "#e9c46a", "#e76f51", "#8ecae6", "#219ebc"]
bars = ax6.barh(topics, scores, color=colors_topics, edgecolor='white', linewidth=0.8)
for b, v in zip(bars, scores):
    ax6.text(b.get_width() + 2, b.get_y() + b.get_height()/2, str(v), va='center', fontsize=10, fontweight='bold', color=PRIMARY)
ax6.set_xlabel('Keyword Frequency Score', fontweight='bold')
ax6.set_title('Recurring Topic Clusters (Keyword Frequency Across All Questions)', fontsize=15, fontweight='bold', color=PRIMARY)
ax6.spines['top'].set_visible(False)
ax6.spines['right'].set_visible(False)
ax6.xaxis.set_major_locator(mticker.MaxNLocator(integer=True))
chart6_b64 = fig_to_base64(fig6)


# ── Chart 7: Topic by Question Type ─────────────────────────────────
fig7, ax7 = plt.subplots(figsize=(12, 7))
topic_names = [t[0] for t in topic_scores_sorted]
x = np.arange(len(topic_names))
width = 0.25
mcq_vals = [mcq_topics.get(t, 0) for t in topic_names]
short_vals = [short_topics.get(t, 0) for t in topic_names]
long_vals = [long_topics.get(t, 0) for t in topic_names]
ax7.bar(x - width, mcq_vals, width, label='MCQs', color=MCQ_COLOR, edgecolor='white', linewidth=0.5)
ax7.bar(x, short_vals, width, label='Short', color=SHORT_COLOR, edgecolor='white', linewidth=0.5)
ax7.bar(x + width, long_vals, width, label='Long', color=LONG_COLOR, edgecolor='white', linewidth=0.5)
ax7.set_ylabel('Keyword Frequency Score', fontweight='bold')
ax7.set_title('Topic Distribution by Question Type', fontsize=15, fontweight='bold', color=PRIMARY)
ax7.set_xticks(x)
ax7.set_xticklabels(topic_names, rotation=45, ha='right', fontsize=9)
ax7.legend(framealpha=0.9, edgecolor='#ddd')
ax7.spines['top'].set_visible(False)
ax7.spines['right'].set_visible(False)
ax7.yaxis.set_major_locator(mticker.MaxNLocator(integer=True))
chart7_b64 = fig_to_base64(fig7)


# ── Chart 8: Short Question Volume (detailed) ───────────────────────
fig8, ax8 = plt.subplots(figsize=(10, 5))
short_by_year = year_type['Short'].values
mcqs_by_year = year_type['MCQs'].values
long_by_year = year_type['Long'].values
ax8.bar(years_labels, short_by_year, color=SHORT_COLOR, edgecolor='white', linewidth=0.8, alpha=0.85, label='Short Questions')
ax8.plot(years_labels, mcqs_by_year, color=MCQ_COLOR, linewidth=2.5, marker='s', markersize=9, label='MCQs (stable at 15)')
ax8.plot(years_labels, long_by_year, color=LONG_COLOR, linewidth=2.5, marker='D', markersize=9, label='Long Questions (stable at 3)')
avg_short = short_by_year.mean()
ax8.axhline(y=avg_short, color=SHORT_COLOR, linestyle='--', alpha=0.5, linewidth=1)
ax8.text(0.5, avg_short + 0.5, f'Mean: {avg_short:.1f}', color=SHORT_COLOR, fontsize=9, fontstyle='italic')
ax8.set_ylabel('Number of Questions', fontweight='bold')
ax8.set_xlabel('Examination Year', fontweight='bold')
ax8.set_title('The Short Question Volatility: The Only Type That Varies', fontsize=15, fontweight='bold', color=PRIMARY)
ax8.legend(framealpha=0.9, edgecolor='#ddd')
ax8.spines['top'].set_visible(False)
ax8.spines['right'].set_visible(False)
ax8.yaxis.set_major_locator(mticker.MaxNLocator(integer=True))
chart8_b64 = fig_to_base64(fig8)


# ── Additional Metrics ──────────────────────────────────────────────
overall_avg = total_questions / len(years_list)
avg_by_type = df.groupby('type').size() / len(years_list)
max_year = year_totals.idxmax()
max_val = year_totals.max()
min_year = year_totals.idxmin()
min_val = year_totals.min()
range_val = max_val - min_val

# Long question sub-part analysis
long_df = df[df['type'] == 'Long'].copy()
long_df['sub_parts'] = long_df['question'].apply(lambda q: len(str(q).split('$')))
avg_subparts = long_df['sub_parts'].mean()

# Topic diversity: unique topics touched per year (approximate by vocabulary)
def unique_words_for_year(y):
    text = ' '.join(df[df['year'] == y]['question'].apply(clean_text))
    words = [w for w in text.split() if w not in STOP_WORDS and len(w) > 2]
    return len(set(words))

year_diversity = {y: unique_words_for_year(y) for y in years_list}


# ── Build HTML Report ──────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>BIEK Computer Science 12th Class Past Paper Analysis (2015–2025)</title>
<style>
:root {{
    --primary: {PRIMARY};
    --secondary: {SECONDARY};
    --accent: {ACCENT};
    --highlight: {HIGHLIGHT};
    --neutral: {NEUTRAL};
    --light-bg: {LIGHT_BG};
    --mcq: {MCQ_COLOR};
    --short: {SHORT_COLOR};
    --long: {LONG_COLOR};
}}

* {{ box-sizing: border-box; margin: 0; padding: 0; }}

body {{
    font-family: 'Segoe UI', 'DejaVu Sans', system-ui, -apple-system, sans-serif;
    line-height: 1.7;
    color: #333;
    background: #f0f2f5;
}}

.container {{
    max-width: 1100px;
    margin: 0 auto;
    background: white;
    box-shadow: 0 0 40px rgba(0,0,0,0.08);
}}

/* ── Cover / Hero ── */
.hero {{
    background: linear-gradient(135deg, var(--primary) 0%, #152b45 100%);
    color: white;
    padding: 70px 60px 50px;
    text-align: center;
}}
.hero h1 {{
    font-size: 2.4em;
    font-weight: 800;
    margin-bottom: 12px;
    letter-spacing: -0.5px;
    line-height: 1.2;
}}
.hero .subtitle {{
    font-size: 1.15em;
    color: #a8c8e8;
    max-width: 700px;
    margin: 0 auto 25px;
}}
