    bottom += vals
ax2.set_ylabel('Number of Questions', fontweight='bold')
ax2.set_xlabel('Examination Year', fontweight='bold')
ax2.set_title('Question Type Composition by Year', fontsize=15, fontweight='bold', color=PRIMARY)
ax2.legend(loc='upper right', framealpha=0.9, edgecolor='#ddd')
ax2.yaxis.set_major_locator(mticker.MaxNLocator(integer=True))
ax2.spines['top'].set_visible(False)
ax2.spines['right'].set_visible(False)
chart2_b64 = fig_to_base64(fig2)


# ── Chart 3: Percentage Share (Stacked Area / 100% bar) ───────────
fig3, ax3 = plt.subplots(figsize=(10, 5))
pct_data = year_type.div(year_totals, axis=0) * 100
for idx, qtype in enumerate(['MCQs', 'Short', 'Long']):
    ax3.plot(years_labels, pct_data[qtype].values, color=bar_colors[idx], linewidth=2.5, marker='o', markersize=6, label=qtype)
ax3.set_ylabel('Percentage of Total (%)', fontweight='bold')
